//lxrtxdy!
#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
constexpr i64 INF = 1000000000LL;
constexpr int MAX_VERTEX = 7100;

struct FlowGraph {
    struct Edge {
        int src, dst;
        i64 flow, capacity;
    };

    int source_id, sink_id;
    vector<Edge> edge_list;
    vector<int> adj[MAX_VERTEX];
    int depth[MAX_VERTEX], next_edge[MAX_VERTEX];

    void clear_all() {
        edge_list.clear();
        for (int i = 0; i < MAX_VERTEX; ++i) adj[i].clear();
    }

    void connect(int u, int v, i64 cap) {
        edge_list.push_back({u, v, 0, cap});
        edge_list.push_back({v, u, 0, 0});
        adj[u].push_back(edge_list.size() - 2);
        adj[v].push_back(edge_list.size() - 1);
    }

    bool bfs_level() {
        fill(depth, depth + MAX_VERTEX, -1);
        queue<int> q;
        q.push(source_id);
        depth[source_id] = 0;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto &e = edge_list[idx];
                if (e.capacity > e.flow && depth[e.dst] == -1) {
                    depth[e.dst] = depth[u] + 1;
                    q.push(e.dst);
                }
            }
        }
        return depth[sink_id] != -1;
    }

    i64 dfs_flow(int u, i64 flow) {
        if (u == sink_id || !flow) return flow;
        i64 total_pushed = 0;
        for (int &i = next_edge[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto &e = edge_list[idx];
            if (depth[e.dst] == depth[u] + 1 && e.capacity > e.flow) {
                i64 pushed = dfs_flow(e.dst, min(flow, e.capacity - e.flow));
                if (pushed) {
                    e.flow += pushed;
                    edge_list[idx ^ 1].flow -= pushed;
                    total_pushed += pushed;
                    flow -= pushed;
                    if (!flow) break;
                }
            }
        }
        return total_pushed;
    }

    i64 compute_max_flow() {
        i64 total = 0;
        while (bfs_level()) {
            memset(next_edge, 0, sizeof(next_edge));
            i64 pushed;
            while ((pushed = dfs_flow(source_id, INF)) > 0)
                total += pushed;
        }
        return total;
    }
};

FlowGraph fg;
char board[2][14][14];
bool visited_coord[14][14];
int time_cost[14][14];
int grid_size, max_time;
int target_vertex[103];

void bfs_from_start(int sx, int sy) {
    for (int i = 0; i < 14; ++i)
        fill(time_cost[i], time_cost[i] + 14, 111);
    queue<tuple<int, int, int>> q;
    time_cost[sx][sy] = 0;
    q.emplace(sx, sy, 0);

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [r, c, d] = q.front(); q.pop();
        if (visited_coord[r][c]) continue;
        visited_coord[r][c] = true;
        time_cost[r][c] = d;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 1 && nr <= grid_size && nc >= 1 && nc <= grid_size &&
                !visited_coord[nr][nc] && board[0][nr][nc] != 'Y') {
                q.emplace(nr, nc, d + 1);
            }
        }
    }
}

int encode_node(int level, int r, int c) {
    return level * grid_size * grid_size + (r - 1) * grid_size + c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> grid_size >> max_time;
    for (int i = 1; i <= grid_size; ++i) cin >> (board[0][i] + 1);
    for (int i = 1; i <= grid_size; ++i) cin >> (board[1][i] + 1);

    fg.clear_all();
    fg.source_id = 0;
    fg.sink_id = MAX_VERTEX - 2;

    int start_r = 0, start_c = 0;
    for (int i = 1; i <= grid_size; ++i) {
        for (int j = 1; j <= grid_size; ++j) {
            if (board[0][i][j] == 'Z') {
                start_r = i; start_c = j;
                break;
            }
        }
    }

    for (int i = 1; i <= grid_size * grid_size; ++i)
        target_vertex[i] = MAX_VERTEX - 3 - (grid_size * grid_size - i);

    bfs_from_start(start_r, start_c);

    for (int i = 1; i <= grid_size; ++i) {
        for (int j = 1; j <= grid_size; ++j) {
            if (isdigit(board[0][i][j]))
                fg.connect(fg.source_id, encode_node(0, i, j), board[0][i][j] - '0');
            if (isdigit(board[1][i][j]))
                fg.connect(target_vertex[encode_node(0, i, j)], fg.sink_id, board[1][i][j] - '0');
            fg.connect(encode_node(0, i, j), target_vertex[encode_node(0, i, j)], INF);
        }
    }

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    for (int t = 1; t <= max_time; ++t) {
        for (int r = 1; r <= grid_size; ++r) {
            for (int c = 1; c <= grid_size; ++c) {
                if (board[0][r][c] == 'Y' || board[0][r][c] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr >= 1 && nr <= grid_size && nc >= 1 && nc <= grid_size &&
                        board[0][nr][nc] != 'Y' && board[0][nr][nc] != 'Z' &&
                        time_cost[r][c] >= t && time_cost[nr][nc] >= t) {
                        fg.connect(encode_node(t - 1, nr, nc), encode_node(t, r, c), INF);
                    }
                }
                fg.connect(encode_node(t, r, c), target_vertex[encode_node(0, r, c)], INF);
            }
        }
    }

    cout << fg.compute_max_flow() << '\n';
    return 0;
}
